head.script:
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "Organization",
      "@id": "https://ranaix.com/#organization",
      "name": "Ranaix",
      "url": "https://ranaix.com/",
      "logo": {
        "@type": "ImageObject",
        "url": "https://ranaix.com/logo.png"
      },
      "description": "Ranaix adalah productivity tech integrator yang membantu organisasi membangun sistem operasional melalui custom software, website development, mobile app, dan integrasi sistem.",
      "sameAs": [
        "https://linkedin.com/company/ranaix",
        "https://instagram.com/ranaix"
      ]
    },
    {
      "@type": "SoftwareCompany",
      "@id": "https://ranaix.com/#company",
      "name": "Ranaix",
      "url": "https://ranaix.com/",
      "areaServed": {
        "@type": "Country",
        "name": "Indonesia"
      },
      "serviceType": [
        "Custom Software Development",
        "Website Development",
        "Mobile App Development",
        "System Integration"
      ],
      "parentOrganization": {
        "@id": "https://ranaix.com/#organization"
      }
    },
    {
      "@type": "WebSite",
      "@id": "https://ranaix.com/#website",
      "url": "https://ranaix.com/",
      "name": "Ranaix",
      "description": "Custom software, jasa pembuatan website, mobile app, dan integrasi sistem untuk meningkatkan produktivitas bisnis.",
      "publisher": {
        "@id": "https://ranaix.com/#organization"
      },
      "inLanguage": "id-ID"
    },
    {
      "@type": "Service",
      "@id": "https://ranaix.com/services/custom-software",
