        "@id": "https://ranaix.com/#organization"
      },
      "description": "Pengembangan custom software untuk membantu organisasi membangun sistem operasional yang produktif dan terintegrasi."
    },
    {
      "@type": "Service",
      "@id": "https://ranaix.com/services/website-development",
      "name": "Jasa Pembuatan Website",
      "provider": {
        "@id": "https://ranaix.com/#organization"
      },
      "description": "Jasa pembuatan website profesional untuk mendukung operasional dan kehadiran digital bisnis."
    },
    {
      "@type": "Service",
      "@id": "https://ranaix.com/services/mobile-app",
      "name": "Mobile App Development",
      "provider": {
        "@id": "https://ranaix.com/#organization"
      },
      "description": "Pengembangan aplikasi mobile untuk membantu bisnis menghadirkan layanan digital yang lebih efisien dan terintegrasi."
    }
  ]
